import { test as base, expect } from '@playwright/test';

type Todo = { id: number; title: string };

// Fixture that seeds a todo through the API and deletes it afterwards.
const test = base.extend<{ seededTodo: Todo }>({
  seededTodo: async ({ page }, use) => {
    const res = await page.request.post('/api/todos', { data: { title: 'Seeded by fixture' } });
    const todo = (await res.json()) as Todo;
    await use(todo);
    await page.request.delete(`/api/todos/${todo.id}`); // teardown
  },
});

test('shows the seeded todo', async ({ page, seededTodo }) => {
  await page.goto('/todos');
  await expect(page.getByText(seededTodo.title)).toBeVisible();
});
